# Generated by curate-skills
# Workflow: wordcount_mapreduce_histogram
# Function: generate_words

"""Entry point of the wordcount MapReduce workflow.

Synthesizes a reproducible corpus of exactly 500 whitespace-separated words,
drawn from a fixed built-in vocabulary with a fixed random seed, and uploads it
as a single plain-text file for the ranked map step to read.
"""

import os
import random
import tempfile

# Fixed built-in vocabulary (50 lowercase, punctuation-free English words).
VOCABULARY = [
    "alpha", "beta", "gamma", "delta", "epsilon",
    "river", "mountain", "forest", "desert", "ocean",
    "data", "model", "signal", "sensor", "sample",
    "cloud", "stream", "cluster", "kernel", "vector",
    "north", "south", "east", "west", "center",
    "summer", "winter", "spring", "autumn", "season",
    "light", "shadow", "color", "pattern", "texture",
    "stone", "water", "fire", "wind", "earth",
    "bridge", "tower", "garden", "harbor", "valley",
    "quiet", "bright", "ancient", "hidden", "distant",
]

# Number of words in the generated corpus and the seed that makes it reproducible.
WORD_COUNT = 500
RANDOM_SEED = 42
WORDS_PER_LINE = 10


def generate_words(folder: str, output1: str) -> None:
    faasr_log(
        "generate_words: generating %d words from a %d-word vocabulary (seed=%d)"
        % (WORD_COUNT, len(VOCABULARY), RANDOM_SEED)
    )

    rng = random.Random(RANDOM_SEED)
    words = [rng.choice(VOCABULARY) for _ in range(WORD_COUNT)]

    if len(words) != WORD_COUNT:
        message = "generate_words: expected %d words, built %d" % (WORD_COUNT, len(words))
        faasr_log(message)
        raise ValueError(message)

    lines = [
        " ".join(words[start:start + WORDS_PER_LINE])
        for start in range(0, WORD_COUNT, WORDS_PER_LINE)
    ]
    text = "\n".join(lines) + "\n"

    # Verify the uploaded text really tokenizes to exactly WORD_COUNT words.
    token_count = len(text.split())
    if token_count != WORD_COUNT:
        message = (
            "generate_words: corpus tokenizes to %d whitespace-separated words, expected %d"
            % (token_count, WORD_COUNT)
        )
        faasr_log(message)
        raise ValueError(message)

    local_file = os.path.join(tempfile.gettempdir(), "corpus.txt")
    with open(local_file, "w", encoding="utf-8") as handle:
        handle.write(text)

    faasr_put_file(local_file=local_file, remote_folder=folder, remote_file=output1)
    faasr_log(
        "generate_words: wrote %s (%d words, %d distinct, %d lines) to folder %s"
        % (output1, token_count, len(set(words)), len(lines), folder)
    )
